//! Cross-implementation test vectors (`test-vectors/vectors.json`, generated by `packages/core`) and
//! self-generated known answers for the parts of the protocol the server implements.

mod common;

use std::path::PathBuf;

use common::{Room, TestServer, b64u};
use ed25519_dalek::{Signer, SigningKey, VerifyingKey};
use lincor_server::crypto;
use reqwest::{Method, StatusCode};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

fn vectors() -> Option<Value> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../test-vectors/vectors.json");
    let text = std::fs::read_to_string(&path).ok()?;
    Some(serde_json::from_str(&text).expect("vectors.json is valid JSON"))
}

fn seed(hex_seed: &str) -> [u8; 32] {
    hex::decode(hex_seed).unwrap().try_into().unwrap()
}

fn text(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

#[test]
fn room_ids_match_the_typescript_core() {
    let Some(v) = vectors() else {
        eprintln!("test-vectors/vectors.json not present; skipping");
        return;
    };
    let rooms = v["room"].as_array().expect("room vectors");
    assert!(!rooms.is_empty());
    for r in rooms {
        let pub_bytes: [u8; 32] = crypto::b64u_decode_array(r["auth_pub_b64u"].as_str().unwrap()).unwrap();
        assert_eq!(crypto::room_id_for(&pub_bytes), r["room_id"].as_str().unwrap());
        let key = SigningKey::from_bytes(&seed(r["auth_seed_hex"].as_str().unwrap()));
        assert_eq!(b64u(key.verifying_key().as_bytes()), r["auth_pub_b64u"].as_str().unwrap());
        assert!(crypto::is_room_id(r["room_id"].as_str().unwrap()));
    }
}

#[test]
fn request_signatures_match_the_typescript_core() {
    let Some(v) = vectors() else {
        eprintln!("test-vectors/vectors.json not present; skipping");
        return;
    };
    let requests = v["request"].as_array().expect("request vectors");
    assert!(!requests.is_empty());
    for r in requests {
        let message = crypto::request_message(
            r["method"].as_str().unwrap(),
            r["target"].as_str().unwrap(),
            r["body_utf8"].as_str().unwrap().as_bytes(),
            &text(&r["ts"]),
            r["nonce"].as_str().unwrap(),
        );
        assert_eq!(hex::encode(&message), r["message_hex"].as_str().unwrap(), "message bytes for {}", r["target"]);
        let pub_bytes: [u8; 32] = crypto::b64u_decode_array(r["auth_pub_b64u"].as_str().unwrap()).unwrap();
        assert_eq!(crypto::room_id_for(&pub_bytes), r["room_id"].as_str().unwrap());
        let sig: [u8; 64] = crypto::b64u_decode_array(r["sig_b64u"].as_str().unwrap()).unwrap();
        assert!(crypto::verify(&VerifyingKey::from_bytes(&pub_bytes).unwrap(), &message, &sig), "signature verifies");
        // Ed25519 is deterministic: our own signature over the same message is byte-identical.
        let key = SigningKey::from_bytes(&seed(r["auth_seed_hex"].as_str().unwrap()));
        assert_eq!(b64u(&key.sign(&message).to_bytes()), r["sig_b64u"].as_str().unwrap());
    }
}

/// The server accepts envelopes produced by the TypeScript core as they are.
#[tokio::test]
async fn typescript_envelopes_are_accepted() {
    let Some(v) = vectors() else {
        eprintln!("test-vectors/vectors.json not present; skipping");
        return;
    };
    for p in v["participant"].as_array().into_iter().flatten() {
        assert!(crypto::is_id16(p["participant_id"].as_str().unwrap()));
    }
    let s = TestServer::start().await;
    let room_vector = &v["room"][0];
    let room = Room::from_seed(seed(room_vector["auth_seed_hex"].as_str().unwrap()));
    assert_eq!(room.id, room_vector["room_id"].as_str().unwrap());
    for e in v["event"].as_array().into_iter().flatten() {
        let envelope = json!({"cid": e["cid"], "sender": e["sender"], "data": e["data"]});
        let (status, body) = s.send_json(&room, Method::POST, &room.path("/events"), &envelope).await;
        assert_eq!(status, StatusCode::CREATED, "{body}");
        let (_, page) = s.get(&room, &room.path(&format!("/events?after={}", body["seq"].as_i64().unwrap() - 1))).await;
        assert_eq!(page["events"][0]["data"], e["data"]);
    }
}

/// Known answers computed independently of `crypto::room_id_for` / `request_message`.
#[test]
fn self_generated_known_answers() {
    let key = SigningKey::from_bytes(&[42u8; 32]);
    let pub_bytes = key.verifying_key().to_bytes();
    let mut h = Sha256::new();
    h.update(b"lincor/v1/room");
    h.update(pub_bytes);
    let room_id = b64u(&h.finalize());
    assert_eq!(crypto::room_id_for(&pub_bytes), room_id);
    assert_eq!(room_id.len(), 43);

    let target = format!("/api/v1/rooms/{room_id}/events");
    let body = br#"{"cid":"AAECAwQFBgcICQoLDA0ODw","sender":"91zCv0A2MKzOXHS3JdF8yA","data":"AAAA"}"#;
    let mut expected = b"lincor/v1/req\nPOST\n".to_vec();
    expected.extend_from_slice(target.as_bytes());
    expected.push(b'\n');
    expected.extend_from_slice(hex::encode(Sha256::digest(body)).as_bytes());
    expected.extend_from_slice(b"\n1760000000000\nAAECAwQFBgcICQoLDA0ODw");
    let message = crypto::request_message("POST", &target, body, "1760000000000", "AAECAwQFBgcICQoLDA0ODw");
    assert_eq!(message, expected);
    let sig = key.sign(&message).to_bytes();
    assert!(crypto::verify(&key.verifying_key(), &message, &sig));
    assert_eq!(key.sign(&message).to_bytes(), sig, "deterministic");
}
